// Generates lib/src/states_data.g.dart (palette.json and states.json) and lib/src/motion_data.g.dart
// (motion/*.json) from the repo's spec/ folder, embedding each file's text verbatim.
//
// Run from packages/flutter after any change to spec/:
//   dart run tool/gen_spec_data.dart
// test/spec_drift_test.dart fails when a generated file and spec/ disagree.
//
// Two files, not one, so the static library (lib/static.dart) imports only the states and never
// the motion data: a static-only app does not carry the baked clips.
//
// Why generated Dart files and not an asset copy: a Flutter package cannot declare assets outside
// its own folder, and a generated source file gives the player its data synchronously (no asset
// bundle, no async first frame, works in plain unit tests), the same way the web package embeds
// spec/ in src/spec-data.ts.
import 'dart:io';

/// The generated states file, relative to packages/flutter.
const String statesOutputPath = 'lib/src/states_data.g.dart';

/// The generated motion file, relative to packages/flutter.
const String motionOutputPath = 'lib/src/motion_data.g.dart';

/// The spec folder, relative to packages/flutter.
const String specPath = '../../spec';

/// The text of every generated file for the spec folder [spec], by output path.
Map<String, String> generate(Directory spec) => {
  statesOutputPath: _generateStates(spec),
  motionOutputPath: _generateMotion(spec),
};

String _read(Directory spec, String rel) {
  final text = File('${spec.path}/$rel').readAsStringSync();
  if (text.contains("'''")) {
    throw StateError(
      "$rel contains ''' and cannot be embedded in a raw string",
    );
  }
  return text.endsWith('\n') ? text : '$text\n';
}

StringBuffer _header(String what) => StringBuffer()
  ..writeln('// GENERATED by tool/gen_spec_data.dart from spec/. Do not edit.')
  ..writeln(
    '// Regenerate: dart run tool/gen_spec_data.dart (in packages/flutter).',
  )
  ..writeln('// $what')
  ..writeln('// ignore_for_file: lines_longer_than_80_chars')
  ..writeln();

String _generateStates(Directory spec) {
  final b =
      _header('Palette and states (no motion clips); see motion_data.g.dart.')
        ..writeln('/// spec/palette.json, verbatim.')
        ..writeln("const String paletteJson = r'''")
        ..write(_read(spec, 'palette.json'))
        ..writeln("''';")
        ..writeln()
        ..writeln('/// spec/states.json, verbatim.')
        ..writeln("const String statesJson = r'''")
        ..write(_read(spec, 'states.json'))
        ..writeln("''';");
  return b.toString();
}

String _generateMotion(Directory spec) {
  final motionDir = Directory('${spec.path}/motion');
  final ids =
      motionDir
          .listSync()
          .whereType<File>()
          .map((f) => f.uri.pathSegments.last)
          .where((n) => n.endsWith('.json'))
          .map((n) => n.substring(0, n.length - 5))
          .toList()
        ..sort();
  final b =
      _header(
          'Baked motion clips; the static library does not import this file.',
        )
        ..writeln('/// spec/motion/<id>.json, verbatim, by clip id.')
        ..writeln('const Map<String, String> motionJson = {');
  for (final id in ids) {
    b
      ..writeln("  '$id': r'''")
      ..write(_read(spec, 'motion/$id.json'))
      ..writeln("''',");
  }
  b.writeln('};');
  return b.toString();
}

void main() {
  final spec = Directory(specPath);
  if (!spec.existsSync()) {
    stderr.writeln('Run from packages/flutter: $specPath not found.');
    exitCode = 1;
    return;
  }
  final out = generate(spec);
  for (final e in out.entries) {
    File(e.key).writeAsStringSync(e.value);
    stdout.writeln('wrote ${e.key}');
  }
}
